import{_ as t,o as n,c as a,ak as i}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy technical design","description":"Game design · Data contract · Delivery preparation","frontmatter":{"title":"Chainy technical design","description":"Game design · Data contract · Delivery preparation","source":"docs/technical-design.md","category":"Game & system design","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/technical-design.md","filePath":"content/docs/technical-design.md"}'),r={name:"content/docs/technical-design.md"};function o(s,e,d,c,l,h){return n(),a("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-technical-design">Chainy technical design<a class="header-anchor" href="#chainy-technical-design" aria-label="Link to this section">​</a></h1><p><a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">Game design</a> · <a href="/Chainy-Docs/content/docs/design/database-schema.html">Data contract</a> · <a href="/Chainy-Docs/content/docs/planning/lesson-collection-delivery.html">Delivery preparation</a></p><p><strong>Documentation and preparation only until the owner&#39;s explicit FINAL approval.</strong> This is a proposed architecture, not an implementation report or authorization to modify or run Unity.</p><h2 id="current-scope">Current scope<a class="header-anchor" href="#current-scope" aria-label="Link to this section">​</a></h2><p>The game is an offline Android journey through Web3, Blockchain, then AI. Each world has a tutorial, 13 ordered lessons, three distinct minigames, and a required 13-question review with one question per lesson. Ordinary collection or successful minigame completion records the corresponding encyclopedia entry. Wrong review answers repeat with feedback until all 13 are correct; saved review completion unlocks the next world. AI activities are authored teaching simulations. No economy, network backend, teacher service, export feature, voucher system, dashboard, standalone Wordle, or BlockMatch is part of this design.</p><h2 id="evidence-and-reuse">Evidence and reuse<a class="header-anchor" href="#evidence-and-reuse" aria-label="Link to this section">​</a></h2><p>The <a href="/Chainy-Docs/content/docs/project-baseline.html#current-implementation-evidence">November 11 audit</a> recorded Unity 6000.3.25f1, Plastic SCM changeset 185, and existing movement, dialogue, quest UI, encyclopedia, profiles, and SQLite infrastructure. All 57 existing Wordle EditMode tests passed before new implementation. Those checks cover legacy code only; they do not demonstrate the new journey, nine activities, or Android acceptance. Android Build Support was missing; the attempted installation was cancelled and readiness remains unverified.</p><table><thead><tr><th>Responsibility</th><th>Proposed contract</th><th>Audited reuse candidate</th></tr></thead><tbody><tr><td>Presentation</td><td>Render committed state and send intentions; no SQL or direct completion changes</td><td>Existing movement, dialogue, quest, and encyclopedia views</td></tr><tr><td>Journey progress</td><td>Own tutorial, lesson order, prerequisites, collection, review completion, and access guards per profile</td><td>Existing profile and progress helpers need compatibility review</td></tr><tr><td>Activities</td><td>Apply each GDD success rule and return a result bound to its originating profile/world/lesson</td><td>Existing activity infrastructure; none of the nine new activities is established by the audit</td></tr><tr><td>Scene lifecycle</td><td>Admit one transition, block duplicate input, and restore the originating island checkpoint</td><td>Existing scene and input patterns need integration verification</td></tr><tr><td>Persistence</td><td>Reuse <code>IDatabaseSystem</code> and the queued <code>DatabaseBridge.RunInTransactionAsync</code> boundary</td><td>Existing SQLite connection and transaction infrastructure</td></tr><tr><td>Authored content</td><td>Supply stable lesson, activity, and question IDs plus content version</td><td>Existing ScriptableObject/content patterns; select one packaged authority during approved development</td></tr></tbody></table><p>Keep View → Handler → Service commands, typed notifications, and existing ServiceRegistry conventions. One progress service owns the journey rules; views and activities consume read-only state. Avoid a second database connection, a replacement manager framework, or duplicated editable lesson/quiz content.</p><h2 id="proposed-command-boundaries">Proposed command boundaries<a class="header-anchor" href="#proposed-command-boundaries" aria-label="Link to this section">​</a></h2><p>Every command identifies the expected profile and relevant world, lesson, or attempt. An activity launch also identifies its originating session so a late callback cannot affect a different session or profile. Serialize mutations and revalidate persisted state inside the transaction.</p><table><thead><tr><th>Operation</th><th>Guard and committed outcome</th></tr></thead><tbody><tr><td>Load profile</td><td>Load supported data before enabling play; distinguish a new profile from a read failure</td></tr><tr><td>Finish tutorial</td><td>Set that unlocked world&#39;s orientation complete; repeated completion is harmless</td></tr><tr><td>Advance encounter</td><td>For the current minigame, save item then NPC prerequisites; facility launch requires both</td></tr><tr><td>Record lesson</td><td>Validate the current lesson&#39;s completion type and result; commit lesson, entry, next objective, and encounter reset together</td></tr><tr><td>Start/answer review</td><td>Create an identified 13-question attempt; retain the first response separately from corrected resolution</td></tr><tr><td>Finish review</td><td>Require 13 resolved questions and 13 recorded lessons; commit completion before exposing next-world access</td></tr><tr><td>Abandon/replay review</td><td>Preserve the old attempt; a new attempt starts all 13 questions and never revokes previous world completion</td></tr></tbody></table><p>These are behavior contracts, not implemented method names. The <a href="/Chainy-Docs/content/docs/design/database-schema.html#current-progress-contract">database contract</a> defines their state and transaction invariants.</p><h2 id="scene-and-recovery-behavior">Scene and recovery behavior<a class="header-anchor" href="#scene-and-recovery-behavior" aria-label="Link to this section">​</a></h2><p>Save prerequisites before entering a dedicated minigame scene. Retry restarts its round inside that scene; Exit returns to the originating island with prerequisites preserved and no new entry. Success saves once before returning. If saving fails, retain the unsaved result for Retry Save or explicit discard; closing before commit leaves the lesson incomplete. If saving succeeds but return loading fails, relaunch restores the recorded lesson and next objective.</p><p>Dialogue, quest, encyclopedia, pause, loading, and pending-save states block inappropriate world input. Clear held joystick input when changing overlays or resuming Android. Pause/backgrounding retains the last committed checkpoint; exact animation or mid-round restoration is not promised. Switch profiles only after resolving pending work, clear the old view/state, and reject stale results. Unknown or incompatible saved data is preserved with recovery feedback.</p><h2 id="preparation-handoff">Preparation handoff<a class="header-anchor" href="#preparation-handoff" aria-label="Link to this section">​</a></h2><p>After FINAL approval, validate one ordered lesson and a minigame round trip with save/reload before expanding integration. Then verify all 39 lessons, nine activities, and three 13-question reviews against <a href="/Chainy-Docs/content/docs/requirements/technical-requirements.html">technical acceptance</a>. A named build must pass <a href="/Chainy-Docs/content/docs/hardware-validation.html">reference-device checks</a>; editor results alone do not establish mobile behavior. Preserve integration, QA, manuscript evidence, and rehearsal before the November 21, 2026 pre-final.</p><p>The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/technical-design.html">previous technical document</a> preserves the older component tables, source references, economy requirements, and dated tasks.</p></div>',1)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
